const results = [];
const cards = document.querySelectorAll('a[id*="mntl-card-list-card"]');
cards.forEach(card => {
  const titleEl = card.querySelector('span[class*="card__title"]');
  const title = titleEl ? titleEl.textContent.trim() : '';
  const ratingEl = card.querySelector('div[id*="mntl-recipe-star-rating"]');
  const reviewsEl = card.querySelector('div[id*="mntl-recipe-card-meta"]');
  // Get rating from aria-label or class
  let rating = '';
  if (ratingEl) {
    const ariaLabel = ratingEl.getAttribute('aria-label');
    rating = ariaLabel;
  }
  let reviews = '';
  if (reviewsEl) {
    const text = reviewsEl.textContent.trim();
    reviews = text;
  }
  // Try getting rating from svg class names
  const ratingContainer = card.querySelector('div[id*="recipe-star-rating"]');
  let ratingText = '';
  if (ratingContainer) {
    ratingText = ratingContainer.getAttribute('aria-label') || ratingContainer.title || '';
  }
  results.push({title, rating: rating || ratingText, fullText: card.textContent.replace(/\s+/g, ' ').trim().substring(0, 300)});
});
return results;

