const cards = document.querySelectorAll('a[id*="mntl-card-list-card"]');
const data = [];
cards.forEach((card, i) => {
  const ratingDiv = card.querySelector('div[id*="recipe-star-rating"]');
  const metaDiv = card.querySelector('div[id*="mntl-recipe-card-meta"]');
  const title = card.querySelector('span.card__title')?.textContent.trim() || card.querySelector('span')?.textContent.trim();
  const metaText = metaDiv ? metaDiv.innerText : '';

  // Find rating value
  let ratingValue = '';
  if (ratingDiv) {
    // Look for any text inside rating
    ratingValue = ratingDiv.innerText || ratingDiv.title || ratingDiv.getAttribute('aria-label') || '';
    // Check for star rating data attributes
    if (!ratingValue) {
      const allEls = ratingDiv.querySelectorAll('*');
      for (const el of allEls) {
        const t = el.getAttribute('title') || el.getAttribute('aria-label');
        if (t && (t.includes('star') || /\d/.test(t))) {
          ratingValue = t;
          break;
        }
      }
    }
  }

  // Count filled vs empty stars by inspecting SVG fill attributes
  const svgs = ratingDiv ? ratingDiv.querySelectorAll('svg') : [];
  let filledStars = 0;
  svgs.forEach(svg => {
    const use = svg.querySelector('use');
    if (use) {
      const href = use.getAttribute('href') || use.getAttribute('xlink:href') || '';
      if (href.includes('star-filled') || href.includes('filled')) {
        filledStars++;
      }
    }
  });

  data.push({
    index: i,
    title: title,
    rating: ratingValue,
    metaText: metaText.replace(/\s+/g, ' ').trim(),
    svgCount: svgs.length,
    filledStars: filledStars
  });
});
return data;

const cards = document.querySelectorAll('a[id*="mntl-card-list-card"]');
const data = [];
cards.forEach((card, i) => {
  const ratingDiv = card.querySelector('div[id*="recipe-star-rating"]');
  const title = card.querySelector('span.card__title')?.textContent.trim();
  const metaText = card.querySelector('div[id*="mntl-recipe-card-meta"]')?.innerText || '';

  let fullStars = 0, halfStars = 0;
  if (ratingDiv) {
    ratingDiv.querySelectorAll('svg').forEach(svg => {
      const cls = svg.getAttribute('class') || '';
      if (cls.includes('star-half')) halfStars++;
      else if (cls.includes('icon-star')) fullStars++;
    });
  }

  const rating = fullStars + (halfStars * 0.5);
  // Parse review count
  const match = metaText.replace(/,/g, '').match(/(\d+)/);
  const reviews = match ? parseInt(match[1]) : 0;

  data.push({index: i, title, rating, reviews});
});
return data;

// Find ingredients section
const ingredients = document.querySelectorAll('.mntl-structured-ingredients__list-item, li[class*="ingredient"]');
const ingredientTexts = Array.from(ingredients).map(li => li.textContent.replace(/\s+/g, ' ').trim()).slice(0, 25);
return ingredientTexts;
